import unittest

from solucao import pedaco


class TestUmPedacoDaLista(unittest.TestCase):
    def test_pega_o_meio(self):
        """pedaco devolve do inicio ate um antes do fim"""
        self.assertEqual(pedaco(["a", "b", "c", "d"], 1, 3), ["b", "c"])

    def test_pega_do_comeco(self):
        """pedaco com inicio 0 devolve do comeco"""
        self.assertEqual(pedaco(["a", "b", "c"], 0, 2), ["a", "b"])

    def test_pega_ate_o_fim(self):
        """pedaco com fim passando do tamanho vai ate o fim"""
        self.assertEqual(pedaco(["a", "b", "c"], 1, 9), ["b", "c"])

    def test_pedaco_vazio(self):
        """pedaco com inicio igual ao fim devolve lista vazia"""
        self.assertEqual(pedaco(["a", "b", "c"], 1, 1), [])
